<script setup>import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useCartStore} from '../stores/cart';const route=useRoute(),router=useRouter(),cart=useCartStore();const step=computed(()=>route.params.step||'shipping');const address=ref({name:'Alex Mercer',line:'124 Industrial Way, Suite 300',city:'Neo Tokyo',country:'Japan'});const payment=ref('card');function next(){if(step.value==='shipping')router.push('/checkout/payment');else if(step.value==='payment')router.push('/checkout/review');else router.push('/order-confirmed/TS-88291')}</script><template><section class="checkout-shell"><div class="stepper"><span :class="{active:step==='shipping'}">1 Shipping</span><span :class="{active:step==='payment'}">2 Payment</span><span :class="{active:step==='review'}">3 Review</span></div><div class="checkout-grid"><div class="checkout-form"><template v-if="step==='shipping'"><span class="eyebrow">CHECKOUT / 01</span><h1>Shipping Address</h1><div class="address-card"><b>{{address.name}}</b><p>{{address.line}}<br>{{address.city}}, {{address.country}}</p><button class="text-button">Edit</button></div><button class="button button-ghost">+ Add New Address</button></template><template v-else-if="step==='payment'"><span class="eyebrow">CHECKOUT / 02</span><h1>Payment Method</h1><label class="payment-option"><input v-model="payment" value="card" type="radio"> Credit / Debit Card <span>VISA · MC · AMEX</span></label><div class="form-grid"><label>Card number<input placeholder="4532 9012 3456 7890"></label><label>Cardholder name<input value="ALEX MERCER"></label><label>Expiration date<input placeholder="09 / 28"></label><label>CVC<input placeholder="842"></label></div><p class="secure">256-bit SSL · Secure gateway</p></template><template v-else><span class="eyebrow">CHECKOUT / 03</span><h1>Review Your Order</h1><div class="review-card"><h3>Shipping Address</h3><p>{{address.name}}<br>{{address.line}}<br>{{address.city}}, {{address.country}}</p><button class="text-button">Edit</button></div><div class="review-card"><h3>Payment Method</h3><p>VISA ending in 4242</p><button class="text-button">Edit</button></div></template><button class="button button-blue" @click="next">{{step==='review'?'Place Order':'Continue'}}</button></div><aside class="summary"><h3>Order Summary</h3><div v-for="i in cart.items" :key="i.id"><span>{{i.name}} × {{i.qty}}</span><b>${{(i.price*i.qty).toFixed(2)}}</b></div><hr><div><span>Subtotal</span><b>${{cart.subtotal.toFixed(2)}}</b></div><div><span>Shipping</span><span>Free</span></div><div><span>Estimated Tax</span><span>Calculated</span></div><div class="total"><span>Total</span><b>${{cart.total.toFixed(2)}}</b></div></aside></div></section></template>
